"use strict";

// Fixed vectors generated by scripts/gen_device_wrap_vectors.py. These pin
// the WebCrypto chain: HKDF parameters, P-256 ECDH over raw points, AES-GCM
// AAD framing, and the QRFT chunk round-trip. If any line fails here, the
// extension and the Android app disagree on the wire format.
const V = {
  prfOut: "000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f",
  credId: "202122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f",
  salt: "bdfb5a7aa47d43b0b533ebf8c4ac7c788fade64d4fecca47b142878908f755a1",
  kek: "4e4ecc7b1ce6b4bc0eba673fd19e0366b58de47d74058987138214118f3b5510",
  seedPubRaw: "0420eb2418a4d73b6e941055d4e4c27d3cefe2363114dbc0520489f9bfc314d27d6fd4da9b14eb530e95449d24b9124f98dc2ca4feb3b2a5d8ac1c2549e567a1c8",
  keyId: "8acba938042a256e",
  seedIv: "000102030405060708090a0b",
  seedCt: "9ZzEOA87DyTJ9Z6nGiQC5MM5nPfoQwhObtnOrW1R+Fx4n4oRNAtFvAfeqVUaXu33pceL1SE1F/cKQedWoYncTiCTTIxbz2V6STiypcOGC5KlzZrqRmrnNmM46hobU1AvyCHvICwOu2UlUqfbO8eoXiVJs2eZYtccmoVWCzV1l9qw7VXh8FndwtZaR/VBN7J77apVF/K/zYv/cg==",
  ephPubRaw: "049a781ca6d055a7f30d0c9ff87936c739f6816ef5f5e72b4b946404b0a1a83b2ac19f842945ea2bf65aa1649b2b02ff79854c8d5ecfcd403862e8a97ea66c71c1",
  sharedX: "0316c0e78d036219f2dc2d4813812625c68d6550361578cf3fc1c71b5f7f99e4",
  wrapKek: "57199984d949438d1851612c6452efb5d581f2c333130ee0d578d4797118331c",
  wrapIv: "0102030405060708090a0b0c",
  wrapCt: "",
  aad: "linuxpass-paste-wrap-v1:8acba938042a256e:BJp4HKbQVafzDQyf+Hk2xzn2gW719ecrS5RkBLChqDsqwZ+EKUXqK/ZaoWSbKwL/eYVMjV7PzUA4YuipfqZsccE=",
  payload: '{"itemId":"vec-item-0000","shareId":"local","data":{"type":"login","metadata":{"name":"Vector Test","itemUuid":"vec-item-0000"},"content":{"itemEmail":"","itemUsername":"vector","password":"s3cret-vector","urls":["https://example.test"],"totpUri":"","passkeys":[]}},"state":1}',
};

const out = document.getElementById("out");
function line(ok, label, extra) {
  const d = document.createElement("div");
  d.className = ok ? "ok" : "fail";
  d.textContent = (ok ? "PASS " : "FAIL ") + label + (extra ? " — " + extra : "");
  out.append(d);
}

async function main() {
  try {
    const prfOut = LpWrap.hexToBytes(V.prfOut);
    const credId = LpWrap.hexToBytes(V.credId);

    // 1. PRF salt derivation
    const salt = await LpWrap.prfSalt(credId);
    line(LpWrap.bytesToHex(salt) === V.salt, "prf salt derivation");

    // 2. seed KEK (HKDF-SHA256, info=linuxpass-seed-kek-v1)
    const kek = await LpWrap.hkdf(prfOut, salt, LpWrap.SEED_INFO, 32);
    line(LpWrap.bytesToHex(kek) === V.kek, "seed KEK (HKDF)");

    // 3. unwrap the seed (AES-GCM under KEK) → import pkcs8 → ECDH
    const iv = LpWrap.hexToBytes(V.seedIv);
    const pkcs8 = await crypto.subtle.decrypt(
      { name: "AES-GCM", iv, additionalData: LpWrap.SEED_AAD },
      await crypto.subtle.importKey("raw", kek, { name: "AES-GCM" }, false, ["decrypt"]),
      LpWrap.unb64(V.seedCt));
    const seedPriv = await crypto.subtle.importKey(
      "pkcs8", pkcs8, { name: "ECDH", namedCurve: "P-256" }, false, ["deriveBits"]);
    const epk = await crypto.subtle.importKey(
      "raw", LpWrap.hexToBytes(V.ephPubRaw), { name: "ECDH", namedCurve: "P-256" }, false, []);
    const shared = await crypto.subtle.deriveBits({ name: "ECDH", public: epk }, seedPriv, 256);
    line(LpWrap.bytesToHex(new Uint8Array(shared)) === V.sharedX, "ECDH shared secret");

    // 4. paste KEK + payload decrypt (AAD framing)
    const pasteKek = await LpWrap.hkdf(new Uint8Array(shared), LpWrap.hexToBytes(V.keyId), LpWrap.PASTE_INFO, 32);
    line(LpWrap.bytesToHex(pasteKek) === V.wrapKek, "paste KEK (HKDF)");
    const plain = await crypto.subtle.decrypt(
      { name: "AES-GCM", iv: LpWrap.hexToBytes(V.wrapIv),
        additionalData: new TextEncoder().encode(V.aad) },
      await crypto.subtle.importKey("raw", pasteKek, { name: "AES-GCM" }, false, ["decrypt"]),
      LpWrap.unb64(V.wrapCt));
    line(new TextDecoder().decode(plain) === V.payload, "paste decrypt");

    // 5. QRFT frame round-trip (encode like generator, decode like scanner)
    const text = '{"a":"' + "x".repeat(600) + '"}';
    const frames = LpQrft.buildFrames("selftest", text);
    const r = new LpQrft.Reassembler();
    let res = null;
    for (const f of frames) { const x = r.push(f); if (x) res = x; }
    line(!!res && res.text === text, "QRFT frame round-trip", res && res.text !== text ? "mismatch" : "");

    line(true, "self-test complete");
  } catch (e) {
    line(false, "self-test aborted", String(e && e.message || e));
  }
}
main();